fn two_sum(nums: Vec<i32>, target: i32) -> Option<(usize, usize)> {
    let mut num_to_index = std::collections::HashMap::new();

    for (i, &num) in nums.iter().enumerate() {
        // Calculate the complement that we need to find
        let complement = target - num;

        // Check if the complement exists in the map
        if let Some(&j) = num_to_index.get(&complement) {
            // Ensure that we have distinct indices
            if i > j {
                return Some((j, i));
            }
        }

        // Store the index of the current number
        num_to_index.insert(num, i);
    }

    None
}